'use client';

import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/cn';

/**
 * Section tab row under a hub hero. Sticks to the top when scrolled and
 * highlights the section in view. Tabs are generated by the page from the
 * sections that exist, so a missing service never shows an empty tab.
 */
export function SectionTabs({
  tabs,
  label,
}: {
  tabs: Array<{ id: string; label: string }>;
  label: string;
}) {
  const [active, setActive] = useState(tabs[0]?.id ?? '');
  const listRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const elements = tabs
      .map((tab) => document.getElementById(tab.id))
      .filter((element): element is HTMLElement => Boolean(element));
    if (elements.length === 0) return;
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((entry) => entry.isIntersecting)
          .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
        if (visible[0]) setActive(visible[0].target.id);
      },
      { rootMargin: '-120px 0px -55% 0px' },
    );
    elements.forEach((element) => observer.observe(element));
    return () => observer.disconnect();
  }, [tabs]);

  useEffect(() => {
    const link = listRef.current?.querySelector<HTMLElement>(`[data-tab="${active}"]`);
    link?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  }, [active]);

  return (
    <nav
      aria-label={label}
      className="no-print sticky top-0 z-30 -mx-4 border-b border-line bg-bg px-4 md:-mx-6 md:px-6 lg:top-[var(--topbar-h)] lg:mx-0 lg:px-0"
    >
      <div ref={listRef} className="scrollbar-none flex gap-1 overflow-x-auto">
        {tabs.map((tab) => (
          <a
            key={tab.id}
            href={`#${tab.id}`}
            data-tab={tab.id}
            aria-current={active === tab.id ? 'true' : undefined}
            onClick={() => setActive(tab.id)}
            className={cn(
              'relative inline-flex h-12 flex-none items-center px-3 text-label transition-colors',
              active === tab.id ? 'text-primary' : 'text-muted hover:text-fg',
            )}
          >
            {tab.label}
            <span
              aria-hidden
              className={cn(
                'absolute inset-x-2 bottom-0 h-[3px] rounded-full transition-colors',
                active === tab.id ? 'bg-primary' : 'bg-transparent',
              )}
            />
          </a>
        ))}
      </div>
    </nav>
  );
}
